def fact(W, q, kind, mode):
    k = 1 if mode % 2 == 0 else 4
    q = q.reshape(-1, k)
    z = W
    if kind == 'cubic':
        z = W * (1 + q[0] * W ** 2 + q[1] * W ** 4) + q[2] * W ** 2
    if kind == 'rat':
        z = (W + q[1] * W ** 2) / (1 + q[0] ** 2 * W ** 2)
    if kind == 'sinh':
        z = np.sinh(np.clip((0.1 + abs(q[0])) * W, -10, 10)) / (0.1 + abs(q[0])) + q[1] * W ** 2
    if kind == 'tanh':
        z = np.tanh((0.1 + abs(q[0])) * W) / (0.1 + abs(q[0])) + q[1] * W ** 2
    if kind == 'asinh':
        z = np.arcsinh((0.1 + abs(q[0])) * W) / (0.1 + abs(q[0])) + q[1] * W ** 2
    if kind == 'mix':
        z = W + q[0] * W ** 2 + q[1] * W ** 3 + q[2] * W ** 4
    r = ring(z)
    return np.c_[np.ones(len(W)), W, r] if mode < 2 else np.c_[np.ones(len(W)), W, r, z - W, W ** 2, W ** 3]

def pair(z, diag=True):
    import itertools
    return np.column_stack([z[:, i] * z[:, j] for (i, j) in itertools.combinations_with_replacement(range(z.shape[1]), 2) if diag or i != j])

def poly(z, d):
    import itertools
    return np.column_stack([np.prod(z[:, k], axis=1) for a in range(1, d + 1) for k in itertools.combinations_with_replacement(range(z.shape[1]), a)])

def reg(A, b, r):
    z = A.std(0)
    z[z < 1e-12] = 1
    B = A / z
    if r == 0:
        return np.linalg.lstsq(A, b, rcond=1e-09)[0]
    return np.linalg.solve(B.T @ B + np.diag(np.r_[0, np.full(A.shape[1] - 1, r)]), B.T @ b) / z.reshape((-1,) + (1,) * (b.ndim - 1))
